onClick:
{{
  (async function() {
    const devis = Get_Devis_Detail.data[0];

    // Teste si une intervention est liée au devis
    const hasIntervention = devis?.ID_INTERVENTION && devis.ID_INTERVENTION.toString().trim() !== "";

    // Détermine le statut cible
    const cibleStatut = hasIntervention ? "Sync Demandée" : "Transformation Demandée";
    const msg = hasIntervention 
      ? "Devis transféré vers l'intervention avec succès !" 
      : "Devis transformé en commande client avec succès !";

    try {
      // Exécute la requête SQL en lui passant le statut dynamique
      await Update_Statut_Action_Devis.run({ statut: cibleStatut });
      showAlert(msg, "success");

      // Rafraîchit les données du devis
      Get_Devis_Detail.run();
    } catch (error) {
      showAlert("Erreur lors de l'opération : " + error.message, "error");
    }
  })()
}}

tooltip:
{{ 
  Get_Devis_Detail.data[0]?.ID_INTERVENTION 
    ? "🔄 Transférer vers Intervention" 
    : "🛒 Transformer en Commande" 
}}
